from robot.api import logger

from ..pm_counters import PmCountersFile
from ..resources import CountersResources


class FileCountersFetcher(object):
    def __init__(
        self, file_path=None, local_moid=None, file_fetcher=PmCountersFile(), values_fetcher=CountersResources()
    ):
        self.file_path = (
            file_path
            if file_path
            else file_fetcher.get_next_unpacked_raw_pm_counters_file(output_dirpath=None, remote_host=None)
        )
        self.local_moid = local_moid
        self.file_fetcher = file_fetcher
        self.values_fetcher = values_fetcher
        self.counters_values = []

    def get_all_counters_values(self, counters_list):
        for counter in counters_list:
            self.counters_values.append(self.get_one_counter_values(counter['counter_id']))
        return self.counters_values

    def get_last_counters_values(self, counters_list):
        for counter in counters_list:
            self.counters_values.append(self.get_one_counter_values(counter['counter_id'])[-1])
        return self.counters_values

    def get_one_counter_values(self, counter_id):
        counter_values_list = self.values_fetcher.get_pm_counter_value(
            counter=counter_id, localmoid=self.local_moid, filepath=self.file_path
        )
        logger.debug('counter {} values list: {}'.format(counter_id, counter_values_list))
        if not counter_values_list:
            return ['Counter Not Found in file']
        return counter_values_list
